// 1. Pega o conteúdo de texto que veio do nó HTTP Request
const csvText = $input.first().json.data;

// 2. Divide o texto em linhas
const linhas = csvText.trim().split('\n');

// 3. Extrai o cabeçalho (primeira linha) para as chaves do objeto
const cabecalho = linhas[0].split(',').map(col => col.trim());

// 4. Array que vai agrupar todos os investimentos
const arrayInvestimentos = [];

// 5. Faz um loop por todas as linhas (pulando o cabeçalho no índice 0)
for (let i = 1; i < linhas.length; i++) {
  const linhaAtual = linhas[i].trim();

  if (!linhaAtual) continue;

  const valores = linhaAtual.split(',');
  const objetoJson = {};

  for (let j = 0; j < cabecalho.length; j++) {
    // Para manter a fidelidade, converte números quando possível, ou mantém como texto
    let valorAtual = valores[j] ? valores[j].trim() : "";

    // Tenta converter o campo "minimo" para número caso seja possível (opcional)
    if (cabecalho[j] === 'minimo' && !isNaN(valorAtual)) {
        valorAtual = Number(valorAtual);
    }

    objetoJson[cabecalho[j]] = valorAtual;
  }

  arrayInvestimentos.push(objetoJson);
}

// 6. Retorna um ÚNICO item contendo a lista inteira dentro da propriedade "investimentos"
return [{
  json: {
    investimentos: arrayInvestimentos
  }
}];

const dados = $input.first().json;

// 1. Identifica as listas de clientes e investimentos vindas do nó Merge
const clientes = dados.body ? dados.body.clientes : (dados.clientes || []);
const investimentos = dados.investimentos || [];

const resultados = [];

// Função auxiliar para formatar o valor mínimo como moeda (ex: R$ 1.000,00)
const formataMoeda = (valor) => {
    return Number(valor).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
};

for (const cliente of clientes) {
    // 2. Converte o texto do saldo ("R$ 12.500,00") para formato numérico (12500)
    const saldoTexto = cliente.saldo || "R$ 0,00";
    const saldoLimpo = saldoTexto.replace('R$', '').replace(/\./g, '').replace(',', '.').trim();
    const saldoNum = parseFloat(saldoLimpo);

    // 3. Cruza os dados: Filtra investimentos compatíveis com o perfil e que o saldo cubra o mínimo
    const recomendacoesPossiveis = investimentos.filter(inv => {
        return inv.perfil.toLowerCase() === cliente.perfil.toLowerCase() && inv.minimo <= saldoNum;
    });

    let recomendacao = null;
    let mensagens = [];
    let mensagem_escolhida = "";

    if (recomendacoesPossiveis.length > 0) {
        // Ordena para recomendar o produto de maior valor mínimo acessível ao cliente
        recomendacoesPossiveis.sort((a, b) => b.minimo - a.minimo); 
        recomendacao = recomendacoesPossiveis[0];
        recomendacao.motivo = "saldo_ok";

        // 4. Gera as mensagens dinâmicas
        const valMinimoFormatado = formataMoeda(recomendacao.minimo);

        const msg1 = `Olá ${cliente.nome}! Pelo seu perfil (${cliente.perfil}), uma boa opção é **${recomendacao.produto}** (mínimo ${valMinimoFormatado}). Com seu saldo atual (${saldoTexto}), você já consegue investir. Rentabilidade: ${recomendacao.rentabilidade}.`;
        const msg2 = `Olá ${cliente.nome}! Recomendação para perfil ${cliente.perfil}: **${recomendacao.produto}** (mínimo ${valMinimoFormatado}). Seu saldo (${saldoTexto}) já atende o mínimo. Rentabilidade: ${recomendacao.rentabilidade}.`;
        const msg3 = `${cliente.nome}, indo direto ao ponto: para o perfil ${cliente.perfil}, **${recomendacao.produto}** (mínimo ${valMinimoFormatado}). Você tem ${saldoTexto}, então dá pra aplicar. Rentabilidade: ${recomendacao.rentabilidade}.`;

        mensagens = [msg1, msg2, msg3];
        mensagem_escolhida = mensagens[0];
    }

    // 5. Monta o bloco do cliente no formato exato da sua imagem
    resultados.push({
        nome: cliente.nome,
        email: cliente.email,
        perfil: cliente.perfil,
        saldo_texto: saldoTexto,
        saldo_num: saldoNum,
        recomendacao: recomendacao,
        mensagens: mensagens,
        mensagem_escolhida: mensagem_escolhida
    });
}

// 6. Retorna a raiz estruturada para o Respond to Webhook
return [{
    json: {
        ok: true,
        total_clientes: clientes.length,
        total_investimentos: investimentos.length,
        resultados: resultados
    }
}];

// 1. Pega o array 'resultados' gerado pelo nó anterior
const resultados = $input.first().json.resultados || [];

// Função para garantir a conversão do saldo caso venha em formato de texto
function parseBRL(valor) {
  if (!valor) return 0;
  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

// 2. Transforma cada cliente do array em UM ITEM separado para o n8n
const out = resultados.map(c => {
  const saldoNum = c.saldo_num ?? parseBRL(c.saldo_texto ?? c.saldo);

  return {
    json: {
      email_to: c.email,
      nome: c.nome,
      perfil: c.perfil,
      saldo_texto: c.saldo_texto,
      saldo_num: saldoNum,
      recomendacao: {
        perfil: c.recomendacao.perfil,
        produto: c.recomendacao.produto,
        minimo: c.recomendacao.minimo,
        rentabilidade: c.recomendacao.rentabilidade
      },
      motivo: "saldo_ok",
      mensagem_base: c.mensagem_escolhida,
      copy_rules: {
        idioma: "pt-BR",
        tom: "amigável e profissional",
        tamanho: "curto (4-6 linhas)",
        evitar: [
          "promessas de ganho",
          "garantias",
          "linguagem agressiva"
        ]
      }
    }
  };
});

// 3. Retorna os itens separados (o Output mostrará múltiplos itens em vez de 1)
return out;

