const items = $input.all();
const code2Items = $("Code in JavaScript2").all();

return items.map((item, index) => {
  // Recupera os dados do cliente oriundos do nó Code in JavaScript2
  const j = code2Items[index] ? code2Items[index].json : item.json;

  // Captura o texto retornado pelo nó Message a model acessando o caminho correto
  let rawText = 
    item.json.output?.[0]?.content?.[0]?.text || 
    item.json.output?.text || 
    item.json.text || 
    item.json.content || 
    item.json.message?.content || 
    "";

  // Valores padrão (fallback) caso o LLM tenha retornado apenas texto simples
  let subject = `Sugestão de investimento: ${j.recomendacao?.produto || 'CDB'}`;
  let text_body = typeof rawText === 'string' ? rawText : JSON.stringify(rawText);
  let html_body = `<p>${text_body.replace(/\n/g, '<br>')}</p>`;

  // Tenta decodificar caso o LLM tenha retornado um JSON estruturado
  try {
    const parsed = typeof rawText === 'string' ? JSON.parse(rawText) : rawText;
    if (parsed && typeof parsed === 'object') {
      if (parsed.subject) subject = parsed.subject;
      if (parsed.text_body) text_body = parsed.text_body;
      if (parsed.html_body) html_body = parsed.html_body;
    }
  } catch (e) {
    // Mantém a formatação de fallback caso a resposta não seja um JSON válido
  }

  // Estrutura final padronizada para integração com Gmail / Webhook
  return {
    json: {
      ok: true,
      to: j.email_to || j.email || "",
      subject: subject,
      text_body: text_body,
      html_body: html_body,
      meta: {
        nome: j.nome,
        perfil: j.perfil,
        produto: j.recomendacao?.produto,
        minimo: j.recomendacao?.minimo,
        rentabilidade: j.recomendacao?.rentabilidade,
        motivo: j.motivo
      }
    }
  };
});
